package com.coreauth.validator;
import com.coreauth.validator.canonical.DateTimeLoadPayloadValidator;import com.fasterxml.jackson.databind.ObjectMapper;import com.fasterxml.jackson.databind.node.ObjectNode;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;
class DateTimeLoadPayloadValidatorTest{static final ObjectMapper M=new ObjectMapper();@Test void request(){assertThat(new DateTimeLoadPayloadValidator().validatePayload(req()).errors()).isEmpty();}@Test void response(){assertThat(new DateTimeLoadPayloadValidator().validatePayload(resp()).errors()).isEmpty();}@Test void wrongType(){ObjectNode p=req();((ObjectNode)p.path(DateTimeLoadPayloadValidator.REQUEST_ROOT)).put("LoadType","P");assertRule(p,"DT-REQ-003");}static void assertRule(ObjectNode p,String i){assertThat(new DateTimeLoadPayloadValidator().validatePayload(p).errors()).anyMatch(e->e.reason().contains(i));}static ObjectNode req(){ObjectNode p=M.createObjectNode(),n=p.putObject(DateTimeLoadPayloadValidator.REQUEST_ROOT);n.put("InformationByte","?");n.put("TerminalIdentifier","SYNTHETIC01XX");n.put("LoadType","D");return p;}static ObjectNode resp(){ObjectNode p=M.createObjectNode(),n=p.putObject(DateTimeLoadPayloadValidator.RESPONSE_ROOT);n.put("DataTypeIndicator",":");n.put("DayOfWeek","3");n.put("CurrentDate","260930");n.put("CurrentTime","1530");n.put("CutTime","1700");n.put("Password","123456");return p;}}
